/**
 * Manages the STOMP/WebSocket connection for an active InteractiveSession.
 * Subscribes to every session topic, dispatches payloads into the Redux session
 * slice, and exposes helper functions for sending host/player actions.
 */
import { useEffect, useRef, useCallback } from "react";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";
import { apiBaseUrl } from "../store/emptyApi";
import { useAppDispatch } from "../store/hooks";
import {
  setSession,
  roundStarted,
  roundResultReceived,
  sessionEnded,
  wsErrorReceived,
  answerProgressReceived,
  presenceUpdated,
  votePhaseStarted,
  voteProgressReceived,
  wordCloudUpdated,
  chatMessageReceived,
  reactionReceived,
  teamUpdateReceived,
  sessionSummaryReceived,
  responsesRevealed,
  freezeStateChanged,
  timerStateReceived,
  submissionsClosingReceived,
  type RoundStartPayload,
  type RoundResultPayload,
  type SessionEndedPayload,
  type WsErrorPayload,
  type AnswerProgressPayload,
  type PresencePayload,
  type WordCloudUpdatePayload,
  type ReactionPayload,
  type TeamUpdatePayload,
  type SessionSummaryPayload,
  type ResponsesRevealedPayload,
  type TimerStatePayload,
  type SubmissionsClosingPayload,
} from "../store/interactiveSessionSlice";
import type {
  InteractiveSessionResponse,
  InteractiveSessionChatMessageResponse,
} from "../store/BrainFlexApi";
import type { AnswerPayload } from "../types/elements";
import type {
  VotePhaseStartPayload,
  VoteProgressPayload,
} from "../types/bestAnswer";

export function useInteractiveSessionWebSocket(roomCode: string | null) {
  const dispatch = useAppDispatch();
  const clientRef = useRef<Client | null>(null);

  useEffect(() => {
    if (!roomCode) return;

    const client = new Client({
      webSocketFactory: () => new SockJS(`${apiBaseUrl}/ws`),
      reconnectDelay: 3000,
      onConnect: () => {
        client.subscribe(
          `/topic/interactive-session/${roomCode}/lobby`,
          (msg) => {
            dispatch(
              setSession(JSON.parse(msg.body) as InteractiveSessionResponse),
            );
          },
        );
        client.subscribe(
          `/topic/interactive-session/${roomCode}/round`,
          (msg) => {
            dispatch(roundStarted(JSON.parse(msg.body) as RoundStartPayload));
          },
        );
        client.subscribe(
          `/topic/interactive-session/${roomCode}/roundResult`,
          (msg) => {
            dispatch(
              roundResultReceived(JSON.parse(msg.body) as RoundResultPayload),
            );
          },
        );
        client.subscribe(
          `/topic/interactive-session/${roomCode}/ended`,
          (msg) => {
            dispatch(sessionEnded(JSON.parse(msg.body) as SessionEndedPayload));
          },
        );
        client.subscribe(
          `/topic/interactive-session/${roomCode}/answered`,
          (msg) => {
            dispatch(
              answerProgressReceived(
                JSON.parse(msg.body) as AnswerProgressPayload,
              ),
            );
          },
        );
        client.subscribe(
          `/topic/interactive-session/${roomCode}/votePhase`,
          (msg) => {
            dispatch(
              votePhaseStarted(JSON.parse(msg.body) as VotePhaseStartPayload),
            );
          },
        );
        client.subscribe(
          `/topic/interactive-session/${roomCode}/voted`,
          (msg) => {
            dispatch(
              voteProgressReceived(JSON.parse(msg.body) as VoteProgressPayload),
            );
          },
        );
        client.subscribe(
          `/topic/interactive-session/${roomCode}/wordCloud`,
          (msg) => {
            dispatch(
              wordCloudUpdated(JSON.parse(msg.body) as WordCloudUpdatePayload),
            );
          },
        );
        // Audience engagement (chunk 11): emoji bursts feed ReactionRain on
        // the host view, chat broadcasts feed ChatPanel for everyone. The
        // chat topic carries both new sends AND moderation flips — the slice
        // dedupes on message id so a moderated rebroadcast updates the
        // existing row in place.
        client.subscribe(
          `/topic/interactive-session/${roomCode}/reaction`,
          (msg) => {
            dispatch(reactionReceived(JSON.parse(msg.body) as ReactionPayload));
          },
        );
        client.subscribe(
          `/topic/interactive-session/${roomCode}/chat`,
          (msg) => {
            dispatch(
              chatMessageReceived(
                JSON.parse(msg.body) as InteractiveSessionChatMessageResponse,
              ),
            );
          },
        );
        // Team mode (chunk 12): full team list + membership map on every
        // change; clients replace state rather than merging deltas.
        client.subscribe(
          `/topic/interactive-session/${roomCode}/teams`,
          (msg) => {
            dispatch(
              teamUpdateReceived(JSON.parse(msg.body) as TeamUpdatePayload),
            );
          },
        );
        // Chunk 24 — PRESENTATION end-of-session aggregation. Mutually
        // exclusive with /ended on the wire: subscribing to both is safe
        // because the server only emits one per session based on the frozen
        // SessionFormat.
        client.subscribe(
          `/topic/interactive-session/${roomCode}/summary`,
          (msg) => {
            dispatch(
              sessionSummaryReceived(
                JSON.parse(msg.body) as SessionSummaryPayload,
              ),
            );
          },
        );
        // Chunk 24 — host clicked Reveal on an ON_CLICK round. One-shot per
        // element per session; the slice keeps the elementId so the player
        // and host UIs flip from "waiting" to "showing responses."
        client.subscribe(
          `/topic/interactive-session/${roomCode}/responsesRevealed`,
          (msg) => {
            dispatch(
              responsesRevealed(
                JSON.parse(msg.body) as ResponsesRevealedPayload,
              ),
            );
          },
        );
        // Chunk 25 — host admin controls. submissionsClosing tells participant
        // devices to flush their drafts when the host ends the submit phase;
        // timerState flips the countdown on pause/resume.
        client.subscribe(
          `/topic/interactive-session/${roomCode}/submissionsClosing`,
          (msg) => {
            dispatch(
              submissionsClosingReceived(
                JSON.parse(msg.body) as SubmissionsClosingPayload,
              ),
            );
          },
        );
        client.subscribe(
          `/topic/interactive-session/${roomCode}/timerState`,
          (msg) => {
            dispatch(timerStateReceived(JSON.parse(msg.body) as TimerStatePayload));
          },
        );
        client.subscribe(`/topic/presence`, (msg) => {
          dispatch(presenceUpdated(JSON.parse(msg.body) as PresencePayload));
        });
        client.subscribe(`/user/queue/errors`, (msg) => {
          dispatch(wsErrorReceived(JSON.parse(msg.body) as WsErrorPayload));
        });
      },
    });

    clientRef.current = client;
    client.activate();

    return () => {
      void client.deactivate();
      clientRef.current = null;
    };
  }, [roomCode, dispatch]);

  const send = useCallback((destination: string, body?: object) => {
    const client = clientRef.current;
    if (client?.connected) {
      client.publish({
        destination,
        body: body !== undefined ? JSON.stringify(body) : undefined,
      });
    }
  }, []);

  return {
    sendStart: useCallback(() => {
      send(`/app/interactive-session/${roomCode}/start`);
    }, [roomCode, send]),

    /**
     * Submit a polymorphic answer for the current element. The payload's `kind`
     * discriminator picks the server-side scoring branch.
     */
    sendAnswer: useCallback(
      (elementId: string, payload: AnswerPayload) => {
        send(`/app/interactive-session/${roomCode}/answer`, {
          elementId,
          payload,
        });
      },
      [roomCode, send],
    ),

    /** Cast a vote during the VOTE phase of a Best Answer round. */
    sendVote: useCallback(
      (elementId: string, submissionId: string) => {
        send(`/app/interactive-session/${roomCode}/vote`, {
          elementId,
          submissionId,
        });
      },
      [roomCode, send],
    ),

    sendNextRound: useCallback(() => {
      send(`/app/interactive-session/${roomCode}/nextRound`);
    }, [roomCode, send]),

    sendLeave: useCallback(() => {
      send(`/app/interactive-session/${roomCode}/leave`);
    }, [roomCode, send]),

    sendBoot: useCallback(
      // `playerId` is the session-scoped public handle (no raw userId on the
      // wire — see InteractiveSessionPlayer.playerId on the backend).
      (playerId: string) => {
        send(`/app/interactive-session/${roomCode}/boot`, { playerId });
      },
      [roomCode, send],
    ),

    sendEndInteractiveSession: useCallback(() => {
      send(`/app/interactive-session/${roomCode}/end`);
    }, [roomCode, send]),

    /**
     * Chunk 24 — host manually surfaces the response distribution for the
     * current round when `showResponses` resolves to ON_CLICK. Server is
     * idempotent: only the first call per element per session actually
     * broadcasts. Wire-up also flips the slice's revealedElementIds locally
     * so the host's own button can disable immediately without a round-trip.
     */
    sendRevealNow: useCallback(
      (elementId: string) => {
        send(`/app/interactive-session/${roomCode}/reveal`, { elementId });
        dispatch(responsesRevealed({ round: 0, elementId }));
      },
      [roomCode, send, dispatch],
    ),

    /**
     * Chunk 24 — host flips the current round's response mode. Affects only
     * the current run; never mutates the deck. The slice's frozenElementIds
     * is updated locally so the host's toggle reflects state immediately
     * even before the lobby DTO rebroadcast lands.
     */
    sendFreezeResponses: useCallback(
      (elementId: string, frozen: boolean) => {
        send(`/app/interactive-session/${roomCode}/freeze`, {
          elementId,
          mode: frozen ? "NOT_ACCEPTING_RESPONSES" : "ACCEPTING_RESPONSES",
        });
        dispatch(freezeStateChanged({ elementId, frozen }));
      },
      [roomCode, send, dispatch],
    ),

    /**
     * Chunk 25 — host ends the submit phase for the current round. The server
     * broadcasts submissionsClosing (devices flush drafts), then after a grace
     * window freezes the round and reveals results.
     */
    sendEndSubmitPhase: useCallback(
      (elementId: string) => {
        send(`/app/interactive-session/${roomCode}/endSubmit`, { elementId });
      },
      [roomCode, send],
    ),

    /** Chunk 25 — host restarts the session from round 1 (keeps players, clears scores). */
    sendRestart: useCallback(() => {
      send(`/app/interactive-session/${roomCode}/restart`);
    }, [roomCode, send]),

    /**
     * Chunk 25 — host pauses / resumes the round countdown. The authoritative
     * paused state comes back on /timerState, so no optimistic local dispatch.
     */
    sendPauseTimer: useCallback(() => {
      send(`/app/interactive-session/${roomCode}/pauseTimer`);
    }, [roomCode, send]),

    sendResumeTimer: useCallback(() => {
      send(`/app/interactive-session/${roomCode}/resumeTimer`);
    }, [roomCode, send]),
  };
}
